{
  "name": "BLU 激光功率/能量计",
  "name_en": "BLU Laser Power / Energy Meter",
  "manufacturer": "Gentec-EO",
  "description": "Gentec-EO BLU 是一类用于连接激光探头并读取测量结果的激光功率/能量计接口，可测量激光功率或单次脉冲能量。设备支持 USB 或蓝牙通信，适用于激光实验、光学系统调试、功率监测和能量校准等场景。",
  "description_en": "The Gentec-EO BLU is a laser power and energy meter interface used with compatible sensor heads to read laser power or single-shot pulse energy. It supports USB or Bluetooth communication and is used in laser experiments, optical system setup, power monitoring, and energy calibration.",
  "tag_hints": [
    "laser power measurement",
    "laser energy measurement",
    "single-shot energy",
    "optical power meter",
    "Bluetooth instrument",
    "USB instrument control",
    "wavelength compensation"
  ],
  "actions": [
    {
      "action_name": "auto-anticipation",
      "description": "获取/设置预判处理功能",
      "description_en": "Get/set anticipation processing"
    },
    {
      "action_name": "auto-auto_scale",
      "description": "获取/设置自动量程",
      "description_en": "Get/set auto scale"
    },
    {
      "action_name": "auto-confirm_connection",
      "description": "确认与设备的连接并停止蓝牙搜索",
      "description_en": "Confirm the connection to the device and stop Bluetooth searching"
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开设备连接",
      "description_en": "Disconnect the device"
    },
    {
      "action_name": "auto-scale",
      "description": "获取/设置测量量程",
      "description_en": "Get/set measurement scale"
    },
    {
      "action_name": "auto-scale_down",
      "description": "将测量量程降低一级",
      "description_en": "Decrease the measurement scale by one step"
    },
    {
      "action_name": "auto-scale_up",
      "description": "将测量量程提高一级",
      "description_en": "Increase the measurement scale by one step"
    },
    {
      "action_name": "auto-single_shot_energy_mode",
      "description": "获取/设置单次脉冲能量模式",
      "description_en": "Get/set single-shot energy mode"
    },
    {
      "action_name": "auto-trigger_level",
      "description": "获取/设置能量模式下的触发电平",
      "description_en": "Get/set trigger level in energy mode"
    },
    {
      "action_name": "auto-user_multiplier",
      "description": "获取/设置用户倍率",
      "description_en": "Get/set user multiplier"
    },
    {
      "action_name": "auto-user_offset",
      "description": "获取/设置用户偏置",
      "description_en": "Get/set user offset"
    },
    {
      "action_name": "auto-wavelength",
      "description": "获取/设置波长",
      "description_en": "Get/set wavelength"
    },
    {
      "action_name": "auto-zero_offset",
      "description": "获取/设置零点偏置",
      "description_en": "Get/set zero offset"
    },
    {
      "action_name": "auto-available_scales",
      "description": "获取可用量程列表",
      "description_en": "Get available measurement scales"
    },
    {
      "action_name": "auto-battery_state",
      "description": "获取电池电量状态",
      "description_en": "Get battery charge state"
    },
    {
      "action_name": "auto-current_value",
      "description": "获取当前测量值",
      "description_en": "Get current measured value"
    },
    {
      "action_name": "auto-head_type",
      "description": "获取探头类型",
      "description_en": "Get sensor head type"
    },
    {
      "action_name": "auto-measure_mode",
      "description": "获取当前测量模式",
      "description_en": "Get current measurement mode"
    },
    {
      "action_name": "auto-new_value_ready",
      "description": "获取新测量值是否就绪",
      "description_en": "Get whether a new measurement value is ready"
    },
    {
      "action_name": "auto-usb_state",
      "description": "获取 USB 连接状态",
      "description_en": "Get USB connection state"
    },
    {
      "action_name": "auto-version",
      "description": "获取设备信息",
      "description_en": "Get device information"
    }
  ]
}

